// ==== exakt der Code, der in den n8n Code-Node kommt ====
const today = new Date($now ? $now.toISO().slice(0,10) : new Date().toISOString().slice(0,10));
const brand = $('Your company details').first().json;

const money = (n, cur) => new Intl.NumberFormat('en-IE',
  { style: 'currency', currency: cur || 'EUR' }).format(Number(n) || 0);

// Xero liefert ACCREC-Rechnungen aller Faelligkeiten. Nur wirklich ueberfaellige
// und noch offene interessieren - AmountDue faellt auf 0, sobald bezahlt wurde.
// $input.all() ist die dokumentierte API des Code-Nodes. `items` ist Altlast
// und lieferte hier undefined-Eintraege - der Lauf brach mit
// "Cannot read properties of undefined (reading 'AmountDue')" ab.
const overdue = $input.all()
  .map(i => i.json)
  .filter(Boolean)
  .filter(inv => Number(inv.AmountDue) > 0 && inv.DueDateString
                 && new Date(inv.DueDateString.slice(0,10)) < today);

// Ein Kunde bekommt EINE Mahnung ueber alle seine offenen Rechnungen, nicht eine
// Mail pro Rechnung. Das ist der Unterschied zwischen einer Erinnerung und Spam.
const byContact = new Map();
for (const inv of overdue) {
  const id = inv.Contact?.ContactID || inv.Contact?.Name;
  if (!byContact.has(id)) byContact.set(id, {
    name: inv.Contact?.Name || 'Customer',
    email: inv.Contact?.EmailAddress || '',
    currency: inv.CurrencyCode || 'EUR',
    invoices: [], total: 0, oldestDays: 0,
  });
  const c = byContact.get(id);
  const days = Math.floor((today - new Date(inv.DueDateString.slice(0,10))) / 86400000);
  c.invoices.push({
    number: inv.InvoiceNumber, issued: inv.DateString?.slice(0,10),
    due: inv.DueDateString.slice(0,10), days,
    amount: Number(inv.AmountDue),
    amountText: money(inv.AmountDue, inv.CurrencyCode),
  });
  c.total += Number(inv.AmountDue);
  c.oldestDays = Math.max(c.oldestDays, days);
}

return [...byContact.values()].map(c => {
  const rows = c.invoices.sort((a,b) => b.days - a.days).map(i => `
      <tr><td>${i.number}</td><td>${i.issued}</td><td>${i.due}</td>
          <td class="r ${i.days > 30 ? 'bad' : ''}">${i.days} days</td>
          <td class="r">${i.amountText}</td></tr>`).join('');
  const html = `<!doctype html><html><head><meta charset="utf-8"><style>
  body{font-family:-apple-system,Segoe UI,Roboto,Helvetica,Arial,sans-serif;color:#111;margin:44px}
  h1{font-size:24px;margin:0 0 2px}.muted{color:#666;font-size:13px}
  .bar{height:4px;background:${brand.accentColour};margin:14px 0 22px;border-radius:2px}
  table{width:100%;border-collapse:collapse;margin-top:18px;font-size:14px}
  th{text-align:left;border-bottom:2px solid #222;padding:7px 6px;font-size:12px;text-transform:uppercase;letter-spacing:.04em}
  td{border-bottom:1px solid #e8e8e8;padding:7px 6px}
  .r{text-align:right}.bad{color:#b3261e;font-weight:600}
  .tot{margin-top:20px;font-size:19px;font-weight:700;text-align:right}
  footer{margin-top:34px;font-size:12px;color:#666;border-top:1px solid #e8e8e8;padding-top:12px}
  </style></head><body>
  <h1>${brand.companyName}</h1><div class="muted">${brand.companyAddress}</div>
  <div class="bar"></div>
  <h2 style="font-size:17px;margin:0 0 2px">Statement of overdue invoices</h2>
  <div class="muted">${c.name} &middot; prepared ${today.toISOString().slice(0,10)}</div>
  <table><thead><tr><th>Invoice</th><th>Issued</th><th>Due</th>
    <th class="r">Overdue</th><th class="r">Amount</th></tr></thead>
    <tbody>${rows}</tbody></table>
  <div class="tot">Total outstanding: ${money(c.total, c.currency)}</div>
  <footer>${brand.footerNote}</footer></body></html>`;
  return { json: {
    customer: c.name, email: c.email, invoiceCount: c.invoices.length,
    totalOutstanding: Number(c.total.toFixed(2)), oldestDays: c.oldestDays,
    subject: `${brand.companyName}: ${c.invoices.length} overdue invoice${c.invoices.length>1?'s':''}, ${money(c.total,c.currency)}`,
    html,
  }};
});
